    barWidth = 70,
    barLabels = TRUE,
    barMinLabel = 5,
    showDiverging = FALSE,
    divWidth = 70,
    divNeutral = "auto",
    divLabels = TRUE,
    divMinLabel = 8,
    divNet = FALSE,
    showHeat = FALSE,
    heatPalette = "blues",
    heatLabels = TRUE,
    heatGap = 4,
    showWaffle = FALSE,
    waffleGap = 10,
    showPicto = FALSE,
    pictoShape = "circle",
    pictoSize = 4.5,
    showParliament = FALSE,
    parlSeats = 100,
    parlRows = 4,
    parlSize = 3.2,
    showProfile = FALSE,
    profLines = TRUE,
    profPoints = TRUE,
    profLabels = FALSE,
    showMeans = FALSE,
    meansCi = TRUE,
    meansLevel = 95,
    meansLabels = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("distOrd requires jmvcore to be installed (restart may be required)")

    if ( ! missing(vars)) vars <- jmvcore::resolveQuo(jmvcore::enquo(vars))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(vars), vars, NULL))

    for (v in vars) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- distOrdOptions$new(
        vars = vars,
        orientation = orientation,
        invertVars = invertVars,
        palette = palette,
        reversePalette = reversePalette,
        theme = theme,
        textSize = textSize,
        sortVars = sortVars,
        decimals = decimals,
        legendPos = legendPos,
        legendTitle = legendTitle,
        title = title,
        showN = showN,
        autoSize = autoSize,
        plotWidth = plotWidth,
        plotHeight = plotHeight,
        showBars = showBars,
        barWidth = barWidth,
        barLabels = barLabels,
        barMinLabel = barMinLabel,
        showDiverging = showDiverging,
        divWidth = divWidth,
        divNeutral = divNeutral,
        divLabels = divLabels,
        divMinLabel = divMinLabel,
        divNet = divNet,
        showHeat = showHeat,
        heatPalette = heatPalette,
        heatLabels = heatLabels,
        heatGap = heatGap,
        showWaffle = showWaffle,
        waffleGap = waffleGap,
        showPicto = showPicto,
        pictoShape = pictoShape,
        pictoSize = pictoSize,
        showParliament = showParliament,
        parlSeats = parlSeats,
        parlRows = parlRows,
        parlSize = parlSize,
        showProfile = showProfile,
        profLines = profLines,
        profPoints = profPoints,
        profLabels = profLabels,
        showMeans = showMeans,
        meansCi = meansCi,
        meansLevel = meansLevel,
        meansLabels = meansLabels)

    analysis <- distOrdClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

